use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter()
        .map(|&b| if b >= b'A' && b <= b'Z' { b + 32 } else { b })
        .collect()
}

fn strip_xn(s: &[u8]) -> Vec<u8> {
    if s.len() >= 4 && &s[0..4] == b"xn--" {
        s[4..].to_vec()
    } else {
        s.to_vec()
    }
}

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let domain: Vec<u8> = if args.len() > 1 {
        args[1].as_bytes().to_vec()
    } else {
        b"multi.level.domain.name.test".to_vec()
    };

    let mut r1 = b"xn--".to_vec();
    r1.extend_from_slice(&to_lower(&domain));
    let r2 = strip_xn(&r1);
    let mut r3 = b"xn--".to_vec();
    r3.extend_from_slice(&domain);
    let r4 = strip_xn(&r3);
    let r5 = !domain.is_empty() && domain.len() <= 255;
    let r6 = true;
    let r7 = domain.iter().all(|&b| b < 0x80);
    let r8 = domain.iter().any(|&b| b >= 0x80);
    let r9 = b"mixedcase".to_vec();
    let r10 = to_lower(&domain);
    let r11: Vec<u8> = match domain.iter().rposition(|&b| b == b'.') {
        Some(i) => domain[i + 1..].to_vec(),
        None => domain.clone(),
    };
    let r12 = domain.iter().filter(|&&b| b == b'.').count() + 1;

    let so = std::io::stdout();
    let mut o = so.lock();
    let bs = |v: bool| if v { b"1".to_vec() } else { b"0".to_vec() };
    for line in [
        r1,
        r2,
        r3,
        r4,
        bs(r5),
        bs(r6),
        bs(r7),
        bs(r8),
        r9,
        r10,
        r11,
        format!("{}", r12).into_bytes(),
    ] {
        o.write_all(&line).unwrap();
        o.write_all(b"\n").unwrap();
    }
    o.flush().unwrap();
}

use std::io::{BufRead, Write};
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

fn unhex(s: &str) -> Vec<u8> {
    let s: Vec<char> = s.chars().filter(|c| !c.is_whitespace()).collect();
    s.chunks(2)
        .map(|c| u8::from_str_radix(&c.iter().collect::<String>(), 16).unwrap())
        .collect()
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
}

fn run(prog: &str, arg: Option<&[u8]>) -> Result<Vec<u8>, String> {
    let mut c = Command::new(prog);
    if let Some(a) = arg {
        if a.contains(&0u8) {
            return Err("NUL-in-arg".to_string());
        }
        c.arg(std::ffi::OsString::from_vec(a.to_vec()));
    }
    match c.output() {
        Ok(o) => {
            if !o.status.success() {
                return Err(format!("exit {:?}", o.status.code()));
            }
            Ok(o.stdout)
        }
        Err(e) => Err(format!("spawn err {}", e)),
    }
}

fn main() {
    let bin = "/workspace/dataset/test12_executable";
    let model = "/tmp/idnamodel/model";
    let stdin = std::io::stdin();
    let mut n = 0usize;
    let mut fails = 0usize;
    let so = std::io::stdout();
    let mut out = so.lock();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        if line.trim().is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.splitn(2, '\t');
        let name = parts.next().unwrap().to_string();
        let hexs = parts.next().unwrap_or("").to_string();
        let arg = unhex(&hexs);
        n += 1;
        let a = run(bin, Some(&arg));
        let b = run(model, Some(&arg));
        match (a, b) {
            (Ok(x), Ok(y)) => {
                if x != y {
                    fails += 1;
                    writeln!(out, "DIVERGE\t{}\targhex={}", name, hex(&arg)).unwrap();
                    let xl: Vec<&[u8]> = x.split(|&c| c == b'\n').collect();
                    let yl: Vec<&[u8]> = y.split(|&c| c == b'\n').collect();
                    let m = xl.len().max(yl.len());
                    for i in 0..m {
                        let xi = xl.get(i).copied().unwrap_or(b"<missing>");
                        let yi = yl.get(i).copied().unwrap_or(b"<missing>");
                        if xi != yi {
                            writeln!(
                                out,
                                "  line{} model={} bin={}",
                                i + 1,
                                hex(yi),
                                hex(xi)
                            )
                            .unwrap();
                        }
                    }
                }
            }
            (ea, eb) => {
                writeln!(out, "ERR\t{}\t{:?} {:?}\targhex={}", name, ea.err(), eb.err(), hex(&arg))
                    .unwrap();
            }
        }
    }
    writeln!(out, "== probes={} divergences={}", n, fails).unwrap();
}

use std::io::Write;

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
