// xorshift rng
struct R(u64);
impl R {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

fn main() {
    let so = std::io::stdout();
    let mut o = so.lock();
    macro_rules! emit {
        ($n:expr, $b:expr) => {
            writeln!(o, "{}\t{}", $n, hex(&$b)).unwrap()
        };
    }

    // ---- C: does a preceding byte suppress folding of following ASCII uppercase? ----
    for b in 1u16..=255 {
        let b = b as u8;
        let mut v = vec![b];
        v.extend_from_slice(b"ABCXYZ");
        emit!(format!("C_prefix_{:02x}_caps", b), v);
    }
    // ---- trailing byte after uppercase ----
    for b in 1u16..=255 {
        let b = b as u8;
        let mut v = b"ABC".to_vec();
        v.push(b);
        emit!(format!("C_caps_suffix_{:02x}", b), v);
    }
    // ---- uppercase sandwiched between two copies of byte b ----
    for b in 1u16..=255 {
        let b = b as u8;
        let v = vec![b, b'Q', b, b'W', b];
        emit!(format!("C_sandwich_{:02x}", b), v);
    }

    // ---- D: all-bytes permutations (order dependence of to_lower) ----
    let all: Vec<u8> = (1u16..=255).map(|x| x as u8).collect();
    emit!("D_all_asc", all.clone());
    let mut desc = all.clone();
    desc.reverse();
    emit!("D_all_desc", desc);
    let mut r = R(0x123456789abcdef);
    for i in 0..25 {
        let mut v = all.clone();
        for j in (1..v.len()).rev() {
            let k = r.below((j + 1) as u64) as usize;
            v.swap(j, k);
        }
        emit!(format!("D_all_shuf{}", i), v);
    }
    // interleave every byte with 'A'
    let mut il = Vec::new();
    for b in 1u16..=255 {
        il.push(b as u8);
        il.push(b'A');
    }
    emit!("D_interleave_A", il);
    let mut il2 = Vec::new();
    for b in 1u16..=255 {
        il2.push(b'Z');
        il2.push(b as u8);
    }
    emit!("D_interleave_Z", il2);

    // ---- E: length boundaries built from multibyte + uppercase ----
    let eacute = [0xC3u8, 0xA9];
    for n in [126usize, 127, 128, 129] {
        let mut v = Vec::new();
        for _ in 0..n {
            v.extend_from_slice(&eacute);
        }
        emit!(format!("E_eacute_x{}", n), v);
    }
    for n in [84usize, 85, 86] {
        let mut v = Vec::new();
        for _ in 0..n {
            v.extend_from_slice(&[0xE2, 0x82, 0xAC]); // euro U+20AC
        }
        emit!(format!("E_euro_x{}", n), v);
    }
    for n in [63usize, 64, 65] {
        let mut v = Vec::new();
        for _ in 0..n {
            v.extend_from_slice(&[0xF0, 0x9F, 0x98, 0x80]); // emoji
        }
        emit!(format!("E_emoji_x{}", n), v);
    }
    // boundary: exactly 253,254,255,256,257 bytes, mixed caps + high bytes
    for n in [1usize, 2, 3, 4, 253, 254, 255, 256, 257, 300, 511, 512, 1000, 4096] {
        let mut v = Vec::new();
        for i in 0..n {
            v.push(match i % 4 {
                0 => b'A',
                1 => 0xC3,
                2 => b'Z',
                _ => 0xBF,
            });
        }
        emit!(format!("E_mix_len{}", n), v);
    }
    // 255-byte string whose last byte is a truncated UTF-8 lead
    let mut v = vec![b'A'; 254];
    v.push(0xF0);
    emit!("E_255_trailing_lead", v);
    let mut v = vec![b'A'; 255];
    v.push(0xF0);
    emit!("E_256_trailing_lead", v);

    // ---- F: dot / label interactions with high bytes ----
    let dotcases: Vec<(&str, Vec<u8>)> = vec![
        ("high_dot_high", vec![0xC3, 0x2E, 0xC3]),
        ("dot_after_lead", vec![0xE2, 0x82, 0x2E, 0x43, 0x4F, 0x4D]),
        ("tld_all_high", vec![0x41, 0x2E, 0xD0, 0x9C, 0xD0, 0x9E]),
        ("tld_high_caps_mix", vec![0x41, 0x2E, 0xC3, 0x41, 0x42]),
        ("trailing_dot", b"EXAMPLE.COM.".to_vec()),
        ("two_trailing_dots", b"EXAMPLE.COM..".to_vec()),
        ("leading_dot", b".EXAMPLE.COM".to_vec()),
        ("only_dots", b".....".to_vec()),
        ("dot_only", b".".to_vec()),
        ("empty", b"".to_vec()),
        ("high_only_tld", vec![0x2E, 0xFF]),
        ("dot_then_high", vec![0x2E, 0x80, 0x81, 0x82]),
        ("fullwidth_dot_as_sep", vec![0x41, 0xEF, 0xBC, 0x8E, 0x42]),
        ("ideo_dot_as_sep", vec![0x41, 0xE3, 0x80, 0x82, 0x42]),
        ("mixed_real_and_fake_dots", vec![0x41, 0xEF, 0xBC, 0x8E, 0x42, 0x2E, 0x43]),
        ("many_dots_255", vec![b'.'; 255]),
        ("many_dots_256", vec![b'.'; 256]),
        ("dots_and_caps", b"A.B.C.D.E.F.G.H.I.J.K.L.M.N.O.P".to_vec()),
    ];
    for (n, b) in dotcases {
        emit!(format!("F_{}", n), b);
    }

    // ---- G: xn-- prefix interactions with case + high bytes ----
    let xns: Vec<(&str, Vec<u8>)> = vec![
        ("XN_upper", b"XN--ABC".to_vec()),
        ("Xn_mixed", b"Xn--AbC".to_vec()),
        ("xN_mixed", b"xN--abc".to_vec()),
        ("xn_lower", b"xn--abc".to_vec()),
        ("xn_only", b"xn--".to_vec()),
        ("XN_only", b"XN--".to_vec()),
        ("xn_dash", b"xn-".to_vec()),
        ("xn_nodash", b"xn".to_vec()),
        ("x", b"x".to_vec()),
        ("xn_then_high", vec![0x78, 0x6E, 0x2D, 0x2D, 0xFF]),
        ("XN_then_high", vec![0x58, 0x4E, 0x2D, 0x2D, 0x80]),
        ("double_xn", b"xn--xn--abc".to_vec()),
        ("double_XN", b"XN--XN--ABC".to_vec()),
        ("xn_in_middle", b"a.xn--b".to_vec()),
        ("xn_at_end", b"a.b.xn--".to_vec()),
        ("Xn_fullwidth", vec![0xEF, 0xBD, 0x98, 0x6E, 0x2D, 0x2D]),
        ("xn_with_nbhyphen", vec![0x78, 0x6E, 0xE2, 0x80, 0x91, 0x2D]),
        ("punycode_body_caf", b"xn--caf-dma".to_vec()),
        ("punycode_body_CAF_upper", b"XN--CAF-DMA".to_vec()),
        ("punycode_body_mnchen", b"xn--mnchen-3ya".to_vec()),
        ("punycode_upper_body", b"xn--MNCHEN-3YA".to_vec()),
        ("punycode_bad_body", b"xn--!!!".to_vec()),
        ("punycode_body_high", vec![0x78, 0x6E, 0x2D, 0x2D, 0xC3, 0xA9]),
    ];
    for (n, b) in xns {
        emit!(format!("G_{}", n), b);
    }
}
